            let ring = SKShapeNode(circleOfRadius: CGFloat(max(1, r.radius * s)))
            ring.strokeColor = SKColor(hex: kinds[r.kind].color)
            ring.fillColor = .clear
            ring.lineWidth = 6
            ring.alpha = CGFloat(max(0, min(1, r.alpha)))
            ring.position = point(c.x, c.y)
            effectLayer.addChild(ring)
        }
