            let c = l.toScreen(Box(p.x, p.y, 0, 0))
            let label = SKLabelNode(fontNamed: "Menlo-Bold")
            label.text = p.text
            label.fontSize = CGFloat(max(28, 56 * s))
            label.fontColor = SKColor(hex: spec.game.palette.accent)
            label.alpha = CGFloat(max(0, min(1, p.alpha)))
