    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let t = touches.first else { return }
        let now = t.location(in: self)
        let before = t.previousLocation(in: self)
        let dx = Double(now.x - before.x)
        let dy = -Double(now.y - before.y)  // scene y is up, world y is down
        touchTotal.x += CGFloat(dx)
        touchTotal.y += CGFloat(dy)
        if spec.game.input.scheme != .swipe && spec.game.input.scheme != .lanes {
            send(InputEvent(.drag, dx: raw(dx), dy: raw(dy)))
        }
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        let travelled = max(abs(touchTotal.x), abs(touchTotal.y))
        if travelled < 12 {
            if !started {
                started = true
                restart()  // the first tap starts a fresh session with a fresh seed
            } else if loop.world.ended {
                restart()
            } else {
                send(InputEvent(.tap))
            }
        } else if spec.game.input.scheme == .lanes {
            if abs(touchTotal.x) > abs(touchTotal.y) {
                // One lane per swipe: a drag of +-swipeSpeed (the lane step) in the swipe direction.
                let step = Int64(spec.game.input.swipeSpeed)
                send(InputEvent(.drag, dx: touchTotal.x > 0 ? step : -step, dy: 0))
            }
        } else if spec.game.input.scheme == .swipe {
            let dir: Direction = abs(touchTotal.x) > abs(touchTotal.y)
                ? (touchTotal.x > 0 ? .right : .left)
                : (touchTotal.y > 0 ? .down : .up)  // touchTotal.y already follows world orientation
            send(InputEvent(.swipe, dir: dir))
        }
        send(InputEvent(.release))
    }

    override func touchesCancelled(_ touches: Set<UITouch>, with event: UIEvent?) {
        send(InputEvent(.release))
    }
